use fx_interface_duration::parse_duration;

#[test]
fn parses_seconds_and_minutes() {
    assert_eq!(parse_duration("7s"), Ok(7));
    assert_eq!(parse_duration("3m"), Ok(180));
    assert_eq!(parse_duration("0s"), Ok(0));
}

#[test]
fn rejects_malformed_inputs() {
    for input in ["", "s", "m", "1", "1h", "-1s", "+1s", "1 s", "1ss", "١s"] {
        assert!(parse_duration(input).is_err(), "accepted {input:?}");
    }
}

#[test]
fn rejects_integer_parse_overflow() {
    assert!(parse_duration("18446744073709551616s").is_err());
}

#[test]
fn rejects_minute_multiplication_overflow() {
    let minutes = (u64::MAX / 60 + 1).to_string() + "m";
    assert!(parse_duration(&minutes).is_err());
}
